#include <iostream>
#include <vector>
using namespace std;
int find(vector<int>& p, int x) {
    if (p[x] == x) return x;
    p[x] = find(p, p[x]);
    return p[x];
}

int main() {
    vector<int> p(5);
    for (int i = 0; i < 5; i++) p[i] = i;
    p[find(p, 1)] = find(p, 2);
    cout << (find(p, 1) == find(p, 2)) << endl;
    cout << (find(p, 1) == find(p, 3)) << endl;
    return 0;
}
